import{z as A,x as s,o as B,c as d,q as n,j as i,D as r,d as e,s as l,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"跨境银行与美元周期","description":"","frontmatter":{"title":"跨境银行与美元周期","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/if-crossborder-dollar-cycle.md","filePath":"econ/if-crossborder-dollar-cycle.md","lastUpdated":1791063341000}'),c={name:"econ/if-crossborder-dollar-cycle.md"};function p(h,E,m,D,C,f){const o=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="跨境银行与美元周期" tabindex="-1">跨境银行与美元周期 <a class="header-anchor" href="#跨境银行与美元周期" aria-label="Permalink to &quot;跨境银行与美元周期&quot;">​</a></h1><div class="epigraph"><p>美元潮汐不在贸易账户里，而在全球银行的资产负债表里：美元走弱，海外借款人的抵押品升值，美元信贷扩张；美元走强，同一台机器反向收缩。</p><footer>—— 据 Bruno and Shin, JME 2015 与 REStud 2015；Shin, IMF Economic Review 2012 整理</footer></div><p><a href="/econ/if-fx-risk-premia">上一课</a>把外汇风险溢价收在中介容量上：VIX 与美元紧缩使保费集体上浮。本课把镜头从价格转向数量：全球银行的美元信贷本身如何随美联储与美元进退。主干<a href="/econ/global-financial-cycle">全球金融周期</a>钉了共动，<a href="/econ/bm-international-banking">国际银行与跨境中介</a>写了银行的公司结构与监管错位；本课的缺口是<strong>美元这个币种的特殊性</strong>——离岸美元信贷怎么组织、美元汇率为何与全球杠杆反向、这条链在压力时靠什么托底。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>美联储收紧，世界跟着紧，经典解释给两条通道：贸易（汇率贬值改竞争力）与利率（本币被动加息）。对美元信贷来说，两条都不主要：借款人欠的是美元，借钱的银行不在这两国之间，贸易根本不在链上。缺口是估值渠道：<strong>美元自己的汇率</strong>是全球美元借款人资产负债表的价格。美元贬值时，本币收入与抵押品折成美元变厚，净值上升，借美元的能力上升——美元信贷反而扩张，这与美国本土借款人「美元升值压制信用」的直觉完全相反。</p><p><span class="marginnote">估值渠道可以代个数：一家企业本币收入 100 亿，借了 1 亿美元。美元从 100 贬到 80 本币，同样那笔美元债按本币计从 100 亿降到 80 亿——汇率一动，债务凭空缩了两成，什么都没做就「还掉」了一块。反过来美元升值，就是同样的机器反向加杠杆。</span></p><h3 id="机器的构造" tabindex="-1">机器的构造 <a class="header-anchor" href="#机器的构造" aria-label="Permalink to &quot;机器的构造&quot;">​</a></h3><p>两级结构。核心是全球银行与美国的货币中心，把美元经批发市场（大额存单、回购、FX 掉期）输给外围：非美银行的美元账本、以及直接借美元的海外企业。量的口径在 BIS：美国之外非银部门的美元债务存量，2020 年代初已逾 12 万亿美元。外围银行借短贷长、借美元贷本币，币种与期限双重错配；它们的杠杆目标（Adrian–Shin 的证据）决定信贷量，而不是某地的储蓄缺口。</p><p><span class="marginnote">BIS 口径下，美国之外非银部门的美元债务存量 2020 年代初已过 12 万亿美元；这还不含通过 FX 掉期形成的表外美元敞口——掉期把美元债务移出资产负债表，是美元周期里最难看清的一层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把「美元周期」写成可测对象。第一步，定存量与流量：BIS 银行统计给跨境债权，按币种与借款人部门拆开——只看总量会把美元信贷与全部跨境业务混在一起。第二步，识别估值渠道：美元宽口径汇率与离岸美元信贷增速的负相关，配美联储议息窗口的事件研究；银行层面用美元暴露的差异做截面，暴露深的缩得更多，才算渠道而不是共趋势。第三步，盯价格信号：交叉货币基差是美元压力的价格，走阔先于数量收缩，见<a href="/quant/irp">量化栏的利率平价</a>。顺序不能乱：没有币种拆分，「美元周期」只是一个形容词。</p><p><span class="marginnote">交叉货币基差可以读成「美元荒的价签」：它衡量在同一笔掉期交易里，借美元要比借欧元、日元额外多付多少利息。平时接近零，压力时走阔——2008 年和 2020 年 3 月都曾冲到年化一两个百分点。价格信号走在数量收缩之前，所以它是这条链上最有用的预警灯。</span></p>',12)),(B(),i(t,null,{default:r(()=>[l(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FED%5B%22%E7%BE%8E%E8%81%94%E5%82%A8%E6%94%BF%E7%AD%96%22%5D%20--%3E%20DOL%5B%22%E7%BE%8E%E5%85%83%E6%B1%87%E7%8E%87%22%5D%0A%20%20DOL%20--%3E%20VAL%5B%22%E4%BC%B0%E5%80%BC%E6%B8%A0%E9%81%93%3A%20%E6%8A%B5%E6%8A%BC%E5%93%81%E6%8A%98%E7%BE%8E%E5%85%83%E5%8F%98%E5%8E%9A%E6%88%96%E5%8F%98%E8%96%84%22%5D%0A%20%20VAL%20--%3E%20NET%5B%22%E5%80%9F%E6%AC%BE%E4%BA%BA%E5%87%80%E5%80%BC%E4%B8%8E%E6%8B%85%E4%BF%9D%E8%83%BD%E5%8A%9B%22%5D%0A%20%20NET%20--%3E%20CRED%5B%22%E7%A6%BB%E5%B2%B8%E7%BE%8E%E5%85%83%E4%BF%A1%E8%B4%B7%22%5D%0A%20%20CRED%20--%3E%20DOL%0A%20%20DOL%20--%3E%7C%22%E7%BE%8E%E5%85%83%E5%8D%87%E5%80%BC%22%7C%20BASIS%5B%22%E4%BA%A4%E5%8F%89%E8%B4%A7%E5%B8%81%E5%9F%BA%E5%B7%AE%E8%B5%B0%E9%98%94%22%5D%0A%20%20BASIS%20--%3E%20SWAP%5B%22%E4%BA%92%E6%8D%A2%E7%BA%BF%3A%20%E5%AE%98%E6%96%B9%E5%9C%B0%E6%9D%BF%22%5D%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("机制是一个正反馈加一个保险丝。正反馈：美元贬值 \\(\\rightarrow\\) 借款人净值上升 \\(\\rightarrow\\) 美元信贷扩张 \\(\\rightarrow\\) 全球风险偏好更松、美元更弱——Bruno–Shin 记录的全球银行杠杆与美元的反向关系就是这条回路的均衡痕迹。反向时机器倒转：美联储收紧，美元升值，外围净值缩水，批发美元市场先断，基差走阔把压力标出价格，信贷收缩再反过来推高美元。2008 年的剧本正是批发侧的挤兑——Gorton 与 Metrick 记录了回购市场上抵押品折扣的集体上调：周期反向运转时，压力以批发挤兑而非存款挤兑的形式出现。保险丝在官方侧：美联储对少数央行的"),a("a",{href:"/econ/dollar-swap-lines"},"美元互换线"),e("把离岸美元的地板价格补上——它是事后装置，资格不均，平时不出场。不这么做会错在哪：把美元周期读成贸易失衡（链上没有贸易）；把互换线当成日常工具（它是压力时的地板，不是常备水管）；只看银行账本（表外掉期与债券融资把敞口藏起来）。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"初学者容易以为美联储收紧伤害新兴市场靠的是贸易渠道——美元升值让出口变贵。实际上对离岸美元借款人，主渠道是资产负债表：欠美元的人债务负担随美元升值变重、抵押品折美元变薄。出口竞争力那点变化排在后面，而且来得慢。")],-1)),(B(),i(t,null,{default:r(()=>[l(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TIGHT%5B%22%E7%BE%8E%E8%81%94%E5%82%A8%E6%94%B6%E7%B4%A7%22%5D%20--%3E%20UP%5B%22%E7%BE%8E%E5%85%83%E5%8D%87%E5%80%BC%22%5D%0A%20%20UP%20--%3E%20SHRINK%5B%22%E5%A4%96%E5%9B%B4%E5%80%9F%E6%AC%BE%E4%BA%BA%E5%87%80%E5%80%BC%E7%BC%A9%E6%B0%B4%22%5D%0A%20%20SHRINK%20--%3E%20RUN%5B%22%E6%89%B9%E5%8F%91%E7%BE%8E%E5%85%83%E5%B8%82%E5%9C%BA%E5%85%88%E6%96%AD%22%5D%0A%20%20RUN%20--%3E%20WIDE%5B%22%E4%BA%A4%E5%8F%89%E8%B4%A7%E5%B8%81%E5%9F%BA%E5%B7%AE%E8%B5%B0%E9%98%94%22%5D%0A%20%20WIDE%20--%3E%20CUT%5B%22%E7%A6%BB%E5%B2%B8%E7%BE%8E%E5%85%83%E4%BF%A1%E8%B4%B7%E6%94%B6%E7%BC%A9%22%5D%0A%20%20CUT%20--%3E%7C%22%E7%BE%8E%E5%85%83%E6%9B%B4%E7%A8%80%E7%BC%BA%22%7C%20UP%0A%20%20WIDE%20--%3E%20FUSE%7B%22%E6%9C%89%E6%97%A0%E4%BA%92%E6%8D%A2%E7%BA%BF%E8%B5%84%E6%A0%BC%22%7D%0A%20%20FUSE%20--%3E%7C%22%E6%9C%89%22%7C%20FLOOR%5B%22%E4%BA%92%E6%8D%A2%E7%BA%BF%E6%89%98%E5%BA%95%22%5D%0A%20%20FUSE%20--%3E%7C%22%E6%97%A0%22%7C%20OWN%5B%22%E5%8F%AA%E9%9D%A0%E8%87%AA%E8%BA%AB%E5%82%A8%E5%A4%87%22%5D%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>机器只覆盖银行与类银行渠道：2010 年代美元债券融资占比上升，同一条估值渠道搬进基金与公司债，量的分布变了，机制没变。互换线只盖有资格的司法辖区，无资格者的地板是自身储备——这把话题递给后课的外汇干预。识别也有边界：估值渠道是条件关系，不是每次美联储会议都触发；本币大国的美元敞口相对小，传导弱。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离岸美元信贷是两级银行结构上的批发美元生意，BIS 口径存量逾 12 万亿美元。</li><li>估值渠道：美元汇率是全球美元借款人资产负债表的价格，美元弱则信贷扩、美元强则信贷缩。</li><li>交叉货币基差是这条链的价格信号，互换线是压力时的官方地板。</li><li>表外 FX 掉期是统计盲区，只看银行账本会低估敞口。</li><li>出处：Bruno–Shin, <em>JME</em> 2015 与 <em>REStud</em> 2015；Shin, <em>IMF Economic Review</em> 2012；Adrian–Shin 2010；Gorton–Metrick, <em>JFE</em> 2012；BIS 银行统计。</li></ul>',4))])}const F=A(c,[["render",p]]);export{u as __pageData,F as default};
